Files: Create: k6/sample/lib/config.js, k6/sample/lib/auth.js, k6/sample/01-first-test.js, k6/README.md Interfaces: Produces: BASE_URL: string, API: string (${BASE_URL}/api/v1), PEAK: number, SCALE: number, t(seconds): string, stages(profile: string, peak: number): Array<{duration, target}>, expectOk(res, what): res, login(email, password): string (JWT), authHeaders(token): object, resetPlayground(): string (owner token). Step 1: Write k6/sample/lib/config.js // Settings shared by every script. Override any of them with -e NAME=value. export const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8080'; export const API = `${BASE_URL}/api/v1`; // Expected peak from the NFR. Small by default so a laptop can run it. export const PEAK = Number(__ENV.USERS || 10); // SCALE shrinks every duration for a dry run: SCALE=0.01 turns a 4h soak into about 2.5 minutes. export const SCALE = Number(__ENV.SCALE || 1); export const t = (seconds) => `${Math.max(1, Math.round(seconds * SCALE))}s`; // The six test types from the Performance Testing module, as k6 stages. // "peak" is VUs for ramping-vus, or iterations per second for ramping-arrival-rate. export function stages(profile, peak) { const p = { smoke: [{ duration: t(60), target: Math.min(5, peak) }], load: [ { duration: t(30), target: peak }, { duration: t(1800), target: peak }, { duration: t(60), target: 0 }, ], stress: [ { duration: t(120), target: Math.round(peak * 1.2) }, { duration: t(300), target: Math.round(peak * 1.2) }, { duration: t(120), target: Math.round(peak * 1.5) }, { duration: t(300), target: Math.round(peak * 1.5) }, { duration: t(120), target: peak * 2 }, { duration: t(300), target: peak * 2 }, { duration: t(120), target: 0 }, ], endurance: [ { duration: t(600), target: peak }, { duration: t(14400), target: peak }, { duration: t(300), target: 0 }, ], spike: [ { duration: t(120), target: Math.round(peak / 2) }, { duration: t(5), target: peak * 2 }, { duration: t(180), target: peak * 2 }, { duration: t(5), target: Math.round(peak / 2) }, { duration: t(180), target: Math.round(peak / 2) }, ], }[profile]; if (!p) throw new Error(`Unknown PROFILE "${profile}". Use smoke, load, stress, endurance or spike.`); return p; } Step 2: Write k6/sample/lib/auth.js import http from 'k6/http'; import { API } from './config.js'; // Stop the test with a readable message instead of hundreds of failed requests. export function expectOk(res, what) { if (res.status === 0) throw new Error(`${what}: no response from ${API}. Is the playground running? (docker compose up -d)`); if (res.status >= 400) throw new Error(`${what}: HTTP ${res.status} ${res.body}`); return res; } export function login(email, password) { const res = http.post(`${API}/auth/login`, JSON.stringify({ email, password }), { headers: { 'Content-Type': 'application/json' }, tags: { name: 'POST /auth/login' }, }); return expectOk(res, `login ${email}`).json('token'); } export function authHeaders(token) { return { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }; } // Clean slate: clears orders and payments, order numbers restart at 1001. export function resetPlayground() { const token = login('owner@playground.local', 'Password123!'); expectOk(http.post(`${API}/admin/reset`, null, { headers: authHeaders(token) }), 'reset'); return token; } Step 3: Write k6/sample/01-first-test.js import http from 'k6/http'; import { check, sleep } from 'k6'; import { API } from './lib/config.js'; export const options = { vus: 1, duration: '10s', thresholds: { checks: ['rate==1'], // every check must pass http_req_duration: ['p(95)<500'], }, }; export default function () { const res = http.get(`${API}/menu`); check(res, { 'status is 200': (r) => r.status === 200, 'menu has pizzas': (r) => r.json('pizzas').length > 0, }); sleep(1); } Step 4: Run it Run: cd k6/sample && k6 run 01-first-test.js; echo exit=$? Expected: both checks ✓, thresholds ✓, exit=0. Step 5: Pin Review Focus 1 (playground down) A throwaway script that only calls resetPlayground() in setup(), pointed at a closed port: cd k6/sample printf "import { resetPlayground } from './lib/auth.js';
export function setup() { resetPlayground(); }
export default function () {}
" > _down.js k6 run -e BASE_URL=http://127.0.0.1:9 _down.js 2>&1 | grep -o "Is the playground running?"; echo exit=${PIPESTATUS[0]} rm _down.js Expected: prints Is the playground running? and a non-zero exit. Step 6: Write k6/README.md Content: one-paragraph purpose, link to docs/k6/index.md, prerequisites (k6 v2.2.0, playground running), a table of the five scripts with the command for each (k6 run 01-first-test.js, k6 run 02-auth.js, k6 run 03-order-flow.js, k6 run 04-thresholds.js, k6 run -e PROFILE=load 05-load-model.js), and the -e switches table: BASE_URL, USERS, SCALE, PROFILE, EXECUTOR, RATE, THINK, AUTOPAY, MOCK_DELAY. Step 7: Commit git add k6/ git commit -m "feat(k6): add sample config, auth helpers and first test"
